/** Server-owned export and preview/save workflow; importing does not activate native dimensions. */
@EventBusSubscriber(modid="justepicdimensions")
public final class JEDBundleService {
    private record Plan(String token,String name,String archiveHash,String fingerprint,long revision,long expires,Path root,Map<String,byte[]> files,Map<String,String> stamps,JsonObject review){}
    private static final Map<MinecraftServer,Job> JOBS=new IdentityHashMap<>();
    private static final Map<MinecraftServer,Map<String,Plan>> REVIEWS=new IdentityHashMap<>();
    public static boolean busy(MinecraftServer server){return JOBS.containsKey(server);}
    private static String owner(CommandSourceStack source){return source.getEntity()==null?"console":source.getEntity().getUUID().toString();}
    private static void permission(CommandSourceStack source){if(!source.hasPermission(2)||source.getEntity() instanceof ServerPlayer p&&(!p.hasPermissions(2)||p.hasDisconnected()))throw new JEDDefinitionException("Bundle operations require operator permission level 2");}
    public static String name(String name){if(!name.matches("[a-zA-Z0-9][a-zA-Z0-9_.-]{0,63}")||name.contains("..")||name.matches("(?i)(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:[.].*)?"))throw new JEDDefinitionException("Use a short bundle filename with letters, numbers, dots, underscores or hyphens");return name.endsWith(".zip")?name:name+".zip";}
    public static Path path(Path root,String folder,String name){return JEDBuilderFiles.file(root,"bundles/"+folder+"/"+name(name));}
    public static CompletableFuture<JsonObject> export(CommandSourceStack source,String name,List<ResourceLocation> dimensions,String mode,List<String> extras){return start(source,job->job.export(name,dimensions,mode,extras));}
    public static CompletableFuture<JsonObject> preview(CommandSourceStack source,String name){return start(source,job->job.preview(name));}
    public static CompletableFuture<JsonObject> catalog(CommandSourceStack source){return start(source,Job::catalog);}
    public static CompletableFuture<JsonObject> dependencies(CommandSourceStack source,List<ResourceLocation> dimensions,String mode,List<String> extras){return start(source,job->job.dependencies(dimensions,mode,extras));}
    public static CompletableFuture<JsonObject> install(CommandSourceStack source,String name,String token,boolean replace){return start(source,job->job.install(name,token,replace));}
    private static CompletableFuture<JsonObject> start(CommandSourceStack source,Consumer<Job> action){
        var server=source.getServer();if(!server.isSameThread())throw new IllegalStateException("Bundles require the server thread");permission(source);JEDDefinitionHooks.requireIdle(server);
        if(busy(server)||JEDBuilderService.busy(server)||JEDDimensionManager.isBusy(server))throw new JEDDefinitionException("Wait for the current dimension or configuration operation");var job=new Job(source);JOBS.put(server,job);try{action.accept(job);}catch(Throwable error){job.fail(error);}return job.result;
    }
    private static final class Job {
        final CommandSourceStack source;final MinecraftServer server;final JEDDefinitionManager.State base;final JEDConfigRepository.Selection selection;final JEDDefinitionResources resources;final AutoCloseable lease;
        final ExecutorService worker=Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon(true).name("JED bundle IO").factory());final CompletableFuture<JsonObject> result=new CompletableFuture<>();
        volatile boolean stopped;JEDPreparedDefinitions candidate;JEDRegistryTransaction transaction;Runnable validated;boolean checking;
        Job(CommandSourceStack source){this.source=source;server=source.getServer();base=JEDDefinitionManager.state(server);selection=base.prepared().selection();resources=(JEDDefinitionResources)server.getResourceManager();lease=resources.lease();}
        <T> void background(Supplier<T> work,Consumer<T> next){worker.execute(()->{try{T value=work.get();post(()->{try{check();next.accept(value);}catch(Throwable error){fail(error);}});}catch(Throwable error){post(()->fail(error));}});}
        void post(Runnable action){if(!stopped)server.tell(new TickTask(server.getTickCount(),()->{if(!stopped)action.run();}));}
        void check(){permission(source);if(stopped||JEDDefinitionManager.state(server)!=base)throw new JEDDefinitionException("Bundle review became stale; preview again");}
        void verify(JEDPreparedDefinitions candidate,Runnable done){this.candidate=candidate;var verification=new TreeMap<ResourceLocation,JEDSourceDocument>();for(var entry:candidate.resources().entrySet()){String directory=JEDRegistryResources.directory(entry.getKey());if(directory!=null&&(directory.equals("dimension")||!Objects.equals(candidate.nativeContents().get(entry.getKey()),base.prepared().nativeContents().get(entry.getKey()))))verification.put(entry.getKey(),entry.getValue());}transaction=JEDRegistryTransaction.verification(server.registryAccess(),verification,base.prepared().nativeContents());validated=done;checking=true;}
        void tick(){if(!checking||stopped)return;try{check();long until=System.nanoTime()+2_000_000;do{if(!transaction.prepared())transaction.advance();else{var definitions=candidate.validateBehavior(transaction.ops(),transaction::containsDimension);justepicdimensions.world.JEDWorldControl.validate(server,candidate,definitions);justepicdimensions.world.JEDBorderController.validate(server,candidate,definitions);justepicdimensions.player.JEDPlayerStateController.validate(server,candidate);for(var definition:definitions.values())if(definition.spawnStructure()!=null)candidate.structureAssets().get(definition.spawnStructure().resource());checking=false;validated.run();break;}}while(System.nanoTime()<until);}catch(Throwable error){fail(error);}}
        void catalog(){
            background(()->JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection),prepared->{
                var dimensions=new JsonArray();prepared.resources().keySet().stream()
                    .filter(key->key.getPath().startsWith("dimension/")&&key.getPath().endsWith(".json"))
                    .map(key->ResourceLocation.fromNamespaceAndPath(key.getNamespace(),key.getPath().substring(10,key.getPath().length()-5)).toString())
                    .sorted().forEach(dimensions::add);
                var reply=new JsonObject();reply.addProperty("action","catalog");reply.addProperty("message","");reply.add("dimensions",dimensions);finish(reply);
            });
        }
        void export(String name,List<ResourceLocation> dimensions,String mode,List<String> extras){
            String filename=name(name);if(dimensions.isEmpty()||dimensions.size()>128||new HashSet<>(dimensions).size()!=dimensions.size())throw new JEDDefinitionException("Select 1-128 distinct dimensions");
            JEDDimensionBundle.requireNew(path(selection.activeSource(),"exports",filename));
            background(()->JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection),prepared->verify(prepared,()->background(()->{
                var capture=new Capture(prepared,resources.rawDatapacks(),mode);for(var id:dimensions)capture.dimension(id);for(String extra:extras)capture.extra(extra);var ids=new JsonArray();dimensions.forEach(id->ids.add(id.toString()));var bundle=JEDDimensionBundle.create(mode,ids,capture.requirements(),capture.files,net.minecraft.SharedConstants.getCurrentVersion().getPackVersion(PackType.SERVER_DATA),net.minecraft.SharedConstants.getCurrentVersion().getPackVersion(PackType.CLIENT_RESOURCES));var target=path(selection.activeSource(),"exports",filename);JEDDimensionBundle.write(target,bundle);var reply=new JsonObject();reply.addProperty("action","export");reply.addProperty("file",target.toString());reply.addProperty("files",bundle.files().size());reply.addProperty("message","Exported "+filename+". Client assets can be installed as a normal resource pack.");reply.add("manifest",bundle.manifest());return reply;
            },this::finish)));
        }
        void dependencies(List<ResourceLocation> dimensions,String mode,List<String> extras){
            if(dimensions.isEmpty()||dimensions.size()>128||new HashSet<>(dimensions).size()!=dimensions.size())throw new JEDDefinitionException("Select 1-128 distinct dimensions");
            background(()->JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection),prepared->background(()->{
                var capture=new Capture(prepared,resources.rawDatapacks(),mode);for(var id:dimensions)capture.dimension(id);for(String extra:extras)capture.extra(extra);
                var files=new JsonArray();capture.files.keySet().forEach(files::add);var reply=new JsonObject();reply.addProperty("action","dependencies");reply.addProperty("message","Required files checked");reply.add("included",files);reply.add("requirements",capture.requirements());return reply;
            },this::finish));
        }
        void preview(String name){
            String filename=name(name);background(()->{
                var archive=path(selection.activeSource(),"imports",filename);if(!Files.exists(archive))throw new JEDDefinitionException("Bundle not found: "+filename+"\n\nPlace the bundle ZIP in this server directory:\n"+archive.getParent()+"\n\nThen preview the import again.");var bundle=JEDDimensionBundle.read(archive);for(var raw:bundle.manifest().getAsJsonArray("requirements")){var requirement=raw.getAsJsonObject();if(requirement.get("kind").getAsString().equals("mod")&&!ModList.get().isLoaded(requirement.get("id").getAsString()))throw new JEDDefinitionException("Bundle requires missing mod "+requirement.get("id").getAsString());if(requirement.get("kind").getAsString().equals("reference")&&requirement.get("id").getAsString().startsWith("template:")){String template=requirement.get("id").getAsString().substring(9);if(!Files.isRegularFile(JEDBuilderFiles.file(selection.source(),"templates/"+template+"/level.dat")))throw new JEDDefinitionException("Bundle requires external world template "+template+"; install it before importing");}}
                var files=new TreeMap<>(bundle.files());files.remove("pack.mcmeta");var stamps=new TreeMap<String,String>();var changes=new JsonArray();var edits=new TreeMap<ResourceLocation,JEDSourceDocument>();var assets=new TreeMap<ResourceLocation,byte[]>();
                for(var entry:files.entrySet()){var target=JEDBuilderFiles.file(selection.activeSource(),entry.getKey());String before=JEDBuilderFiles.stamp(target),after=JEDDimensionBundle.hash(entry.getValue());stamps.put(entry.getKey(),before);var change=new JsonObject();change.addProperty("file",entry.getKey());change.addProperty("before",before);change.addProperty("after",after);change.addProperty("status",before.equals(after)?"identical":before.equals("<missing>")?"new":"conflict");changes.add(change);
                    if(entry.getKey().startsWith("data/")){var key=resource(entry.getKey());if(entry.getKey().endsWith(".json"))edits.put(key,new JEDSourceDocument(JEDDimensionBundle.readJson(entry.getValue(),entry.getKey()),"bundle "+filename));else assets.put(key,entry.getValue());}
                }
                var before=JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection);var prepared=JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection,null,edits,assets);
                for(var raw:changes){var change=raw.getAsJsonObject();String path=change.get("file").getAsString();if(path.startsWith("data/")&&path.endsWith(".json")){var key=resource(path);var old=before.resources().get(key);var next=prepared.resources().get(key);if(old!=null&&next!=null&&!old.value().equals(next.value())){change.addProperty("status","conflict");change.addProperty("existing_definition",old.origin(""));}if(old!=null&&JEDDimensionBundle.json(old.value()).length<=2048)change.add("before_json",old.value());if(next!=null&&JEDDimensionBundle.json(next.value()).length<=2048)change.add("after_json",next.value());}}
                var review=new JsonObject();review.addProperty("action","preview");review.addProperty("name",filename);review.addProperty("token",UUID.randomUUID().toString());review.addProperty("message","Review every file. Import saves files; active worlds remain unchanged. Conflicting files require explicit replacement.");review.add("changes",changes);review.add("manifest",bundle.manifest());review.addProperty("requires_client_pack",files.keySet().stream().anyMatch(p->p.startsWith("assets/"))||bundle.manifest().getAsJsonArray("requirements").asList().stream().anyMatch(r->r.getAsJsonObject().get("kind").getAsString().equals("client_asset")));review.addProperty("activation","Use the normal reload/create workflow after saving; existing native generator changes require restart.");var plan=new Plan(review.get("token").getAsString(),filename,JEDBuilderFiles.stamp(archive),before.fingerprint(),base.revision(),System.nanoTime()+600_000_000_000L,selection.activeSource(),Map.copyOf(files),Map.copyOf(stamps),review);return new Preview(plan,prepared);
            },value->verify(value.prepared(),()->{REVIEWS.computeIfAbsent(server,s->new HashMap<>()).put(owner(source),value.plan());var review=value.plan().review().deepCopy();review.addProperty("activation",nextSteps(review.getAsJsonObject("manifest")));finish(review);}));
        }
        void install(String name,String token,boolean replace){
            var plan=REVIEWS.getOrDefault(server,Map.of()).get(owner(source));if(plan==null||!plan.token().equals(token)||!plan.name().equals(name(name))||System.nanoTime()>plan.expires()||plan.revision()!=base.revision()||!plan.root().equals(selection.activeSource()))throw new JEDDefinitionException("No current bundle preview matches this import; preview again");
            if(!replace&&plan.review().getAsJsonArray("changes").asList().stream().anyMatch(row->row.getAsJsonObject().get("status").getAsString().equals("conflict")))throw new JEDDefinitionException("Bundle has conflicting files; review them and explicitly choose replacement");
            REVIEWS.get(server).remove(owner(source));background(()->{
                if(!JEDBuilderFiles.stamp(path(selection.activeSource(),"imports",plan.name())).equals(plan.archiveHash())||!JEDPreparedDefinitions.prepare(resources.rawDatapacks(),selection).fingerprint().equals(plan.fingerprint()))throw new JEDDefinitionException("Bundle or configuration changed since preview; preview again");return true;
            },ignored->{check();String next=nextSteps(plan.review().getAsJsonObject("manifest"));background(()->{if(stopped)throw new CancellationException("Server stopped before bundle installation");var writes=new TreeMap<String,byte[]>();var expected=new TreeMap<String,String>();for(var entry:plan.files().entrySet())if(!JEDDimensionBundle.hash(entry.getValue()).equals(plan.stamps().get(entry.getKey()))){writes.put(entry.getKey(),entry.getValue());expected.put(entry.getKey(),plan.stamps().get(entry.getKey()));}String backup=JEDBundleFiles.commit(selection.activeSource(),writes,plan.stamps());var reply=plan.review().deepCopy();reply.addProperty("action","import");reply.addProperty("backup",backup);reply.addProperty("message","Imported "+plan.name()+". Active dimensions are unchanged. "+next+" Previous files are retained in bundle-backups/"+backup+"/previous.");reply.addProperty("activation",next);return reply;},this::finish);});
        }
        /** The exact commands that activate an import: creation for dimensions not registered yet, reload or restart for the rest. Server thread. */
        String nextSteps(JsonObject manifest){
            var stems=server.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.LEVEL_STEM);var created=new ArrayList<String>();var existing=new ArrayList<String>();
            for(var raw:manifest.getAsJsonArray("dimensions")){var id=ResourceLocation.parse(raw.getAsString());(stems.containsKey(id)?existing:created).add(id.toString());}
            var steps=new StringBuilder();
            // The IDs come from the bundle's own files; say so, so they are not mistaken for fixed or example names.
            if(!created.isEmpty())steps.append(created.size()==1?"Next, create the new dimension it defines, using the ID set in the bundle's files: ":"Next, create the "+created.size()+" new dimensions it defines, using the IDs set in the bundle's files: ").append(String.join(", ",created.stream().map(id->"/jed create "+id).toList())).append(created.size()==1?". Until it exists, /jed reload is refused. ":". Until they exist, /jed reload is refused. ");
            if(!existing.isEmpty())steps.append("For ").append(String.join(", ",existing)).append(", /jed reload applies settings; generator and dimension-type changes apply after a restart.");
            return steps.toString().strip();
        }
        void finish(JsonObject reply){if(stopped)return;stopped=true;JOBS.remove(server,this);worker.execute(this::release);worker.shutdown();result.complete(reply);}
        void fail(Throwable error){if(stopped)return;stopped=true;JOBS.remove(server,this);worker.execute(this::release);worker.shutdown();result.completeExceptionally(error);}
        void release(){try{lease.close();}catch(Exception error){com.mojang.logging.LogUtils.getLogger().warn("Could not release bundle resource lease",error);}}
    }
    private record Preview(Plan plan,JEDPreparedDefinitions prepared){}
    public static ResourceLocation resource(String path){JEDDimensionBundle.path(path);String[] parts=path.split("/",3);return JEDDimensionDefinition.id(parts[1]+":"+parts[2],"bundle resource");}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){var job=JOBS.get(event.getServer());if(job!=null)job.tick();if(event.getServer().getTickCount()%200==0){var reviews=REVIEWS.get(event.getServer());if(reviews!=null){long now=System.nanoTime();reviews.values().removeIf(plan->now>plan.expires());}}}
    @SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent event){if(event.getEntity() instanceof ServerPlayer player){var reviews=REVIEWS.get(player.server);if(reviews!=null)reviews.remove(player.getUUID().toString());}}
    @SubscribeEvent public static void stopping(ServerStoppingEvent event){var job=JOBS.remove(event.getServer());if(job!=null){job.stopped=true;job.worker.execute(job::release);job.worker.shutdown();job.result.completeExceptionally(new CancellationException("Server stopped; committed bundle transactions recover on startup"));}}
    @SubscribeEvent public static void stopped(ServerStoppedEvent event){REVIEWS.remove(event.getServer());}
    private JEDBundleService(){}

    private static final class Capture {
        final JEDPreparedDefinitions prepared;final String mode;final Map<ResourceLocation,JEDSourceDocument> raw,config;final JEDBuilderSources resolver;final Map<ResourceLocation,JsonObject> linked=new HashMap<>();final Set<ResourceLocation> linking=new LinkedHashSet<>();
        final Map<String,byte[]> files=new TreeMap<>();final Set<String> requirements=new TreeSet<>();final net.minecraft.server.packs.resources.ResourceManager packs;
        Capture(JEDPreparedDefinitions prepared,net.minecraft.server.packs.resources.ResourceManager packs,String mode){this.prepared=prepared;this.packs=packs;this.mode=mode;var pack=JEDDatapackSource.read(packs);config=JEDConfigRepository.read(prepared.selection());raw=new TreeMap<>(pack);prepared.catalogue().resources().forEach(raw::putIfAbsent);resolver=new JEDBuilderSources(pack,prepared.catalogue().resources(),config,JEDDimensionOrigins.read(packs),JEDConfigControls.read(prepared.selection()),new ArrayList<>(),false);}
        void dimension(ResourceLocation id){var key=ResourceLocation.fromNamespaceAndPath(id.getNamespace(),"dimension/"+id.getPath()+".json");collect(key,true);var properties=ResourceLocation.fromNamespaceAndPath(id.getNamespace(),JEDDimensionDefinition.DIRECTORY+"/"+id.getPath()+".json");if(prepared.resources().containsKey(properties))collect(properties,true);}
        JsonObject linked(ResourceLocation key){
            if(linked.containsKey(key))return linked.get(key).deepCopy();if(!linking.add(key)||linking.size()>32)throw new JEDDefinitionException("Cannot export cyclic builder source "+key);try{var low=raw.get(key);var high=config.get(key);JsonObject upper=high==null?null:high.value().getAsJsonObject();if(upper!=null&&upper.has(JEDBuilderSources.HEADER)){var header=upper.remove(JEDBuilderSources.HEADER).getAsJsonObject();if(header.get("mode").getAsString().equals("independent"))low=null;else{var source=ResourceLocation.parse(header.get("source").getAsString());low=source.equals(key)?low:new JEDSourceDocument(linked(source),"bundle source "+source);if(low==null&&header.has("fallback"))low=new JEDSourceDocument(header.get("fallback"),"bundle fallback");}}
                JsonObject result;if(low==null)result=Objects.requireNonNull(upper,"Missing property document");else if(upper==null)result=low.value().getAsJsonObject();else{var lower=low.value().getAsJsonObject();lower=justepicdimensions.instance.JEDInstanceStore.blueprint(lower).getAsJsonObject();var settings=lower.deepCopy();settings.remove("format_version");settings.remove("profiles");var profile=new JsonObject();profile.addProperty("format_version",1);if(lower.has("profiles"))profile.add("profiles",lower.get("profiles").deepCopy());profile.add("settings",settings);var id=ResourceLocation.fromNamespaceAndPath("justepicdimensions","bundle_layers/"+JEDDimensionBundle.hash(JEDDimensionBundle.json(lower)).substring(0,24));var profileKey=JEDSettingProfiles.resource(id);linked.put(profileKey,profile);result=upper.deepCopy();var profiles=new JsonArray();profiles.add(id.toString());if(upper.has("profiles"))upper.getAsJsonArray("profiles").forEach(p->profiles.add(p.deepCopy()));result.add("profiles",profiles);}
                result=justepicdimensions.instance.JEDInstanceStore.blueprint(result).getAsJsonObject();linked.put(key,result.deepCopy());return result;
            }finally{linking.remove(key);}
        }
        void collect(ResourceLocation key,boolean force){
            String path="data/"+key.getNamespace()+"/"+key.getPath();if(files.containsKey(path))return;boolean auxiliary=key.getPath().startsWith("justepicdimensions/");if(!force&&!auxiliary&&!config.containsKey(key)&&(key.getNamespace().equals("minecraft")||ModList.get().isLoaded(key.getNamespace()))){requirements.add("resource|"+key);return;}
            JsonElement value;if(linked.containsKey(key))value=linked.get(key).deepCopy();else if(key.getPath().startsWith(JEDDimensionDefinition.DIRECTORY+"/")&&mode.equals("linked"))value=linked(key);else{var document=prepared.resources().get(key);if(document==null)throw new JEDDefinitionException("Missing export dependency "+key);value=document.value();}
            if(key.getPath().startsWith(JEDDimensionDefinition.DIRECTORY+"/")||JEDSettingProfiles.isProfile(key))value=justepicdimensions.instance.JEDInstanceStore.blueprint(value);
            if(key.getPath().startsWith(justepicdimensions.instance.JEDInstancePolicy.DIRECTORY+"/")){var permissions=value.getAsJsonObject().getAsJsonObject("permissions");if(permissions!=null)for(var raw:permissions.entrySet()){var permission=raw.getValue().getAsJsonObject();if(permission.has("rule")){var rule=ResourceLocation.parse(permission.get("rule").getAsString());collect(ResourceLocation.fromNamespaceAndPath(rule.getNamespace(),justepicdimensions.access.JEDAccessRule.DIRECTORY+"/"+rule.getPath()+".json"),true);}}}
            if(value.isJsonObject())value.getAsJsonObject().add(JEDBuilderSources.HEADER,JEDBuilderSources.instruction("independent",key,null));put(path,JEDDimensionBundle.json(value));if(value.isJsonObject()&&(JEDSettingProfiles.isProfile(key)||key.getPath().startsWith(JEDDimensionDefinition.DIRECTORY+"/")))policies(value.getAsJsonObject());scan(value);String directory=JEDRegistryResources.directory(key);if(directory!=null)nativeReferences(value,directory,"");
        }
        void put(String path,byte[] bytes){if(!files.containsKey(path)&&files.size()>=JEDDimensionBundle.MAX_FILES-1)throw new JEDDefinitionException("Too many selected bundle dependencies");long total=bytes.length;for(var entry:files.entrySet())if(!entry.getKey().equals(path))total+=entry.getValue().length;if(bytes.length>JEDDimensionBundle.MAX_FILE||total>JEDDimensionBundle.MAX_BYTES)throw new JEDDefinitionException("Selected bundle dependencies exceed size limits");files.put(path,bytes);}
        void reference(JsonObject root,String section,String field,String directory){if(root.has(section)&&root.get(section).isJsonObject()){var object=root.getAsJsonObject(section);if(object.has(field)){var id=ResourceLocation.parse(JEDJson.string(object.get(field),field));collect(ResourceLocation.fromNamespaceAndPath(id.getNamespace(),directory+"/"+id.getPath()+".json"),true);}}}
        void policies(JsonObject root){
            if(root.has("generation")&&root.getAsJsonObject("generation").has("structure_sets"))for(var element:root.getAsJsonObject("generation").getAsJsonArray("structure_sets")){var id=ResourceLocation.parse(element.getAsString());collect(ResourceLocation.fromNamespaceAndPath(id.getNamespace(),"worldgen/structure_set/"+id.getPath()+".json"),false);}
            for(var id:JEDSettingProfiles.references(root,"bundle profiles"))collect(JEDSettingProfiles.resource(id),true);
            if(root.has("settings"))policies(root.getAsJsonObject("settings"));
            root.remove(justepicdimensions.instance.JEDInstanceStore.MARKER);reference(root,"monitoring","policy",justepicdimensions.monitor.JEDMonitoringPolicy.DIRECTORY);reference(root,"instances","policy",justepicdimensions.instance.JEDInstancePolicy.DIRECTORY);reference(root,"access","rule",justepicdimensions.access.JEDAccessRule.DIRECTORY);reference(root,"mobs","policy",justepicdimensions.mob.JEDMobSpawnPolicy.DIRECTORY);reference(root,"pregeneration","policy",justepicdimensions.pregen.JEDPregenerationPolicy.DIRECTORY);reference(root,"environment","policy",justepicdimensions.environment.JEDEnvironmentPolicy.DIRECTORY);reference(root,"lifecycle","schedule",justepicdimensions.schedule.JEDLifecycleSchedulePolicy.DIRECTORY);
            if(root.has("lifecycle")&&root.getAsJsonObject("lifecycle").has("template"))requirements.add("reference|template:"+root.getAsJsonObject("lifecycle").get("template").getAsString());
            if(root.has("player")){var player=root.getAsJsonObject("player");if(player.has("groups"))for(var group:player.getAsJsonObject("groups").entrySet()){var category=justepicdimensions.player.JEDPlayerCategory.parse(group.getKey(),"bundle player group");collect(category.resource(ResourceLocation.parse(group.getValue().getAsString())),true);}if(player.has("loadouts"))for(var raw:player.getAsJsonObject("loadouts").entrySet()){var rule=raw.getValue().getAsJsonObject();if(rule.has("kit")){var kit=ResourceLocation.parse(rule.get("kit").getAsString());collect(ResourceLocation.fromNamespaceAndPath(kit.getNamespace(),justepicdimensions.player.JEDLoadoutDefinition.DIRECTORY+"/"+kit.getPath()+".json"),true);}}}
            if(root.has("spawn_structure")){var structure=justepicdimensions.structure.JEDStructureDefinition.decode(root.get("spawn_structure"),"bundle structure");asset(structure.resource());}
        }
        void asset(ResourceLocation id){String path="data/"+id.getNamespace()+"/"+id.getPath();if(files.containsKey(path))return;var source=JEDBuilderFiles.file(prepared.selection().source(),path);try{if(Files.isRegularFile(source)){if(Files.size(source)>JEDDimensionBundle.MAX_FILE)throw new JEDDefinitionException("Structure too large: "+id);put(path,Files.readAllBytes(source));return;}var found=packs.getResource(id);if(found.isPresent())try(var input=found.get().open()){put(path,input.readNBytes(JEDDimensionBundle.MAX_FILE+1));return;}requirements.add("resource|"+id);}catch(IOException error){throw new JEDDefinitionException("Cannot export structure "+id,error);}}
        void scan(JsonElement value){
            if(value.isJsonObject()){for(var entry:value.getAsJsonObject().entrySet())if(!entry.getKey().equals(JEDBuilderSources.HEADER))scan(entry.getValue());return;}if(value.isJsonArray()){value.getAsJsonArray().forEach(this::scan);return;}if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())return;String text=value.getAsString();if(text.startsWith("#")){if(JEDDimensionBundle.tagReference(text))requirements.add("reference|"+text);return;}var id=ResourceLocation.tryParse(text);if(id==null||!text.contains(":"))return;if(ModList.get().isLoaded(id.getNamespace())&&!id.getNamespace().equals("justepicdimensions"))requirements.add("mod|"+id.getNamespace());
            if(id.getPath().startsWith("textures/")&&id.getPath().endsWith(".png")){String file="assets/"+id.getNamespace()+"/"+id.getPath();var source=JEDBuilderFiles.file(prepared.selection().source(),file);if(Files.isRegularFile(source))extra(file);else requirements.add("client_asset|"+id);}
        }
        void nativeReferences(JsonElement value,String directory,String path){
            if(value.isJsonObject()){for(var entry:value.getAsJsonObject().entrySet())if(!entry.getKey().equals(JEDBuilderSources.HEADER))nativeReferences(entry.getValue(),directory,path.isEmpty()?entry.getKey():path+"."+entry.getKey());return;}if(value.isJsonArray()){for(var child:value.getAsJsonArray())nativeReferences(child,directory,path);return;}if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())return;String text=value.getAsString();if(!text.contains(":")||text.startsWith("#"))return;var id=ResourceLocation.tryParse(text);if(id==null)return;String field=path.substring(path.lastIndexOf('.')+1);var targets=new LinkedHashSet<String>();
            if(directory.equals("dimension")){if(path.equals("type"))targets.add("dimension_type");else if(field.equals("settings"))targets.add("worldgen/noise_settings");else if(field.equals("biome"))targets.add("worldgen/biome");else if(field.equals("preset"))targets.add("worldgen/multi_noise_biome_source_parameter_list");}
            else if(directory.equals("worldgen/biome")){if(path.startsWith("features"))targets.add("worldgen/placed_feature");if(path.startsWith("carvers"))targets.add("worldgen/configured_carver");}
            else if(directory.equals("worldgen/placed_feature")&&field.equals("feature"))targets.add("worldgen/configured_feature");
            else if(directory.equals("worldgen/configured_feature")&&Set.of("feature","features","default").contains(field))targets.add("worldgen/placed_feature");
            else if(directory.equals("worldgen/noise_settings")&&path.startsWith("noise_router")||directory.equals("worldgen/density_function")&&!field.equals("type")){targets.add(field.equals("noise")?"worldgen/noise":"worldgen/density_function");}
            else if(directory.equals("worldgen/multi_noise_biome_source_parameter_list")&&field.equals("biome"))targets.add("worldgen/biome");
            else if(directory.equals("worldgen/structure_set")&&field.equals("structure"))targets.add("worldgen/structure");
            else if(directory.equals("worldgen/structure")){if(field.equals("asset")){asset(ResourceLocation.fromNamespaceAndPath(id.getNamespace(),(id.getPath().endsWith(".schem")?"justepicdimensions/schematics/":"structure/")+id.getPath()));return;}if(field.equals("start_pool"))targets.add("worldgen/template_pool");else if(field.equals("biomes"))targets.add("worldgen/biome");}
            else if(directory.equals("worldgen/template_pool")){if(field.equals("fallback"))targets.add("worldgen/template_pool");else if(field.equals("processors"))targets.add("worldgen/processor_list");else if(field.equals("location"))asset(ResourceLocation.fromNamespaceAndPath(id.getNamespace(),"structure/"+id.getPath()+".nbt"));}
            for(String target:targets){var key=ResourceLocation.fromNamespaceAndPath(id.getNamespace(),target+"/"+id.getPath()+".json");if(prepared.resources().containsKey(key))collect(key,false);else requirements.add("resource|"+key);}
        }
        void extra(String path){JEDDimensionBundle.path(path);if(path.startsWith("data/")&&path.endsWith(".json")){collect(resource(path),true);return;}if(path.startsWith("data/")){asset(resource(path));if(!files.containsKey(path))throw new JEDDefinitionException("Missing selected bundle asset "+path);return;}var source=JEDBuilderFiles.file(prepared.selection().source(),path);try{if(Files.size(source)>JEDDimensionBundle.MAX_FILE)throw new JEDDefinitionException("Selected asset is too large: "+path);put(path,Files.readAllBytes(source));if(path.endsWith(".png")&&Files.isRegularFile(Path.of(source+".mcmeta")))extra(path+".mcmeta");}catch(IOException error){throw new JEDDefinitionException("Missing selected bundle asset "+path,error);}}
        JsonArray requirements(){var result=new JsonArray();for(String entry:requirements){String[] parts=entry.split("[|]",2);var item=new JsonObject();item.addProperty("kind",parts[0]);item.addProperty("id",parts[1]);result.add(item);}return result;}
    }
}
